{"lesson": "The channel is main total_changes: it counts every direct row change on the main connection, including rolled-back changes, and ignores the other connection. The put conflict mode is INSERT OR REPLACE, since a second put on the same key changes the committed value. The trigger is absent, because the channel equals the direct change count. Committed state is the final committed table contents.", "scope": "Predicts channel, committed_count, and committed_sum for action sequences over the disclosed SQLite family, using main total_changes as the channel and INSERT OR REPLACE as the put mode.", "source": "def investigate(context, acquire):
    history = acquire("history")
    receipts = []
    for h in history:
        if isinstance(h, dict):
            receipts.append(h)

    def simulate(actions, put_mode, channel_mode, trigger):
        main = {}
        other = {}
        main_changes = 0
        other_changes = 0
        main_tx = False
        other_tx = False
        main_pending = None
        other_pending = None

        for a in actions:
            op = a.get("op")
            conn = a.get("connection", "main")
            key = a.get("key")
            value = a.get("value")

            if op == "begin":
                if conn == "main":
                    main_tx = True
                    main_pending = dict(main)
                else:
                    other_tx = True
                    other_pending = dict(other)
            elif op == "commit":
                if conn == "main":
                    main_tx = False
                    main_pending = None
                else:
                    other_tx = False
                    other_pending = None
            elif op == "rollback":
                if conn == "main":
                    if main_pending is not None:
                        main.clear()
                        main.update(main_pending)
                    main_tx = False
                    main_pending = None
                else:
                    if other_pending is not None:
                        other.clear()
                        other.update(other_pending)
                    other_tx = False
                    other_pending = None
            else:
                if conn == "main":
                    if main_tx:
                        table = main_pending
                    else:
                        table = main
                else:
                    if other_tx:
                        table = other_pending
                    else:
                        table = other

                if op == "put":
                    if key in table:
                        if put_mode == "ignore":
                            n = 0
                        else:
                            table[key] = value
                            n = 1
                    else:
                        table[key] = value
                        n = 1
                elif op == "update":
                    if key in table:
                        table[key] = value
                        n = 1
                    else:
                        n = 0
                elif op == "delete":
                    if key in table:
                        del table[key]
                        n = 1
                    else:
                        n = 0
                else:
                    n = 0

                if conn == "main":
                    main_changes += n
                else:
                    other_changes += n

        if channel_mode == "changes":
            channel = main_changes
        elif channel_mode == "total_main":
            channel = main_changes
        else:
            channel = main_changes + other_changes
        if trigger:
            channel += 1

        count = len(main)
        total = 0
        for v in main.values():
            total += v
        return channel, count, total

    def consistent(put_mode, channel_mode, trigger):
        for h in receipts:
            actions = h.get("actions", [])
            obs = h.get("observed", {})
            ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
            if ch != obs.get("channel"):
                return False
            if cnt != obs.get("committed_count"):
                return False
            if sm != obs.get("committed_sum"):
                return False
        return True

    candidates = []
    for put_mode in ["ignore", "replace", "upsert"]:
        for channel_mode in ["changes", "total_main", "total_both"]:
            for trigger in [False, True]:
                if consistent(put_mode, channel_mode, trigger):
                    candidates.append((put_mode, channel_mode, trigger))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    values = []
    for put_mode, channel_mode, trigger in candidates:
        ch, cnt, sm = simulate(actions, put_mode, channel_mode, trigger)
        if goal == "channel":
            values.append(ch)
        elif goal == "committed_count":
            values.append(cnt)
        elif goal == "committed_sum":
            values.append(sm)
        else:
            return {"value": None, "unresolved": True}

    first = values[0]
    for v in values:
        if v != first:
            return {"value": None, "unresolved": True}
    return {"value": first, "unresolved": False}
"}
